        {{ include('blocks/media-frame.html.twig', {'p': {'alt': og_get(v_o, ['name']), 'ratio': '4/3'}}, with_context = false) }}
        {%- set c_3 -%}
          {{ include('compose/Radio.html.twig', {'name': og_s(v_name), 'value': og_s(og_get(v_o, ['id'])), 'checked': og_t(og_eq(v_i, 0))}, with_context = false) }}
