            {{ og_text(og_get(v_o, ['name'])) }}
          {%- endset -%}
          {{ include('compose/Inline.html.twig', {'children': c_2}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/Label.html.twig', {'class': 'flex items-center gap-2 font-medium', 'children': c_3}, with_context = false) }}
        {%- set c_4 -%}
          {{ og_text(og_tpl('{0} · {1}', [og_money(og_get(v_o, ['price']), og_get(v_o, ['currency'])), og_get(v_o, ['note'])])) }}
        {%- endset -%}
        {{ include('compose/Inline.html.twig', {'class': 'text-xs text-muted-foreground', 'children': c_4}, with_context = false) }}
