      {{ include('compose/Box.html.twig', {'class': 'flex flex-col gap-2 rounded p-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', 'attrs': og_attrs(['data-slot', 'option']), 'children': c_5}, with_context = false) }}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/Box.html.twig', {'class': 'grid grid-cols-2 gap-4 md:grid-cols-4', 'children': c_6}, with_context = false) }}
{%- endset -%}
{{ include('compose/Fieldset.html.twig', {'class': 'flex flex-col gap-2', 'attrs': og_attrs(['role', 'radiogroup', 'aria-labelledby', og_tpl('{0}-legend', [v_name]), 'data-slot', 'meat']), 'children': c_7}, with_context = false) }}
